begin;
do $$
declare a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();sport uuid; football uuid; tid uuid; m uuid; final uuid; r jsonb; rules jsonb; ft uuid; fmatch uuid; size_test integer; check_tid uuid; check_rules jsonb;
begin
 if to_regclass('auth.users') is not null then
   insert into auth.users(id,email,email_confirmed_at,aud,role) values(a,a||'@knockout-qa.invalid',now(),'authenticated','authenticated'),(u,u||'@knockout-qa.invalid',now(),'authenticated','authenticated');
   insert into public.profiles(id,username) values(a,'koqa-'||substr(a::text,1,20)),(u,'koqa-'||substr(u::text,1,20)) on conflict do nothing;
 end if;
 insert into public.user_roles values(a,'admin'),(u,'user');
 select id into sport from public.sports where slug='darts';select id into football from public.sports where slug='football';
 rules:='[{"unit":"legs","first_to":6,"winner_points":1,"exact_points":3},{"unit":"sets","first_to":3,"winner_points":2,"exact_points":5}]';
 perform set_config('request.jwt.claim.sub',u::text,true);perform set_config('role','authenticated',true);
 begin perform public.create_knockout_tournament('QA',sport,'players',array['A','B','C'],now()+interval '1 day',rules);raise exception 'FAIL non-admin creation';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',a::text,true);
 tid:=public.create_knockout_tournament('QA knockout',sport,'players',array['QA A','QA B','QA C'],now()+interval '1 day',rules);
 r:=public.get_knockout_schema(tid);
 if jsonb_array_length(r->'matches')<>3 or jsonb_array_length(r->'rounds')<>2 then raise exception 'FAIL full bracket';end if;
 perform public.edit_knockout(tid,'roster',null,'{"names":["QA A","QA B","QA C"]}');
 foreach size_test in array array[2,5,8,16,48,64,128] loop
   select jsonb_agg(jsonb_build_object('unit','legs','first_to',6,'winner_points',1,'exact_points',3)) into check_rules from generate_series(1,ceil(log(2,size_test))::integer);
   check_tid:=public.create_knockout_tournament('QA size '||size_test,sport,'players',array(select 'QA speler '||x from generate_series(1,size_test)x),now()+interval '1 day',check_rules);
   r:=public.get_knockout_schema(check_tid);
   if (select count(*) from jsonb_array_elements(r->'matches')x where not (x->>'bye')::boolean)<>size_test-1 then raise exception 'FAIL number of played matches for %',size_test;end if;
 end loop;
 perform set_config('role','postgres',true);
 if (select count(*) from predict_private.knockout_nodes where tournament_id=tid and is_bye)<>1 then raise exception 'FAIL bye count';end if;
 if exists(select 1 from public.matches x join predict_private.knockout_nodes n on n.match_id=x.id where n.tournament_id=tid and n.is_bye and (x.predictions_enabled or x.home_score is not null)) then raise exception 'FAIL bye scored';end if;
 select match_id into m from predict_private.knockout_nodes where tournament_id=tid and round_no=1 and not is_bye;
 select match_id into final from predict_private.knockout_nodes where tournament_id=tid and round_no=2;
 perform set_config('role','authenticated',true);
 begin perform 1 from predict_private.knockout_nodes;raise exception 'FAIL private table';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',u::text,true);
 begin perform public.get_knockout_schema(tid);raise exception 'FAIL draft leak';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.edit_knockout(tid,'schedule',m,jsonb_build_object('start',now()+interval '1 day','unit','legs','first_to',6));
 perform public.edit_knockout(tid,'schedule',final,jsonb_build_object('start',now()+interval '2 days','unit','sets','first_to',3));
 perform public.edit_knockout(tid,'publish');
 perform set_config('role','postgres',true);
 if not (select predictions_enabled from public.matches where id=m) then raise exception 'FAIL publication opening';end if;
 if (select predictions_enabled from public.matches where id=final) then raise exception 'FAIL placeholder open';end if;
 insert into public.tournament_entries values(tid,u);
 perform set_config('role','authenticated',true);perform set_config('request.jwt.claim.sub',u::text,true);
 perform public.submit_match_prediction(m,6,3);
 begin perform public.submit_match_prediction(final,3,1);raise exception 'FAIL unknown participants';exception when others then if sqlerrm like 'FAIL%' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',a::text,true);
 begin perform public.edit_knockout(tid,'result',m,'{"home_score":6,"away_score":3}');raise exception 'FAIL early result';exception when others then if sqlerrm like 'FAIL%' then raise;end if;end;
 perform set_config('role','postgres',true);
 update public.matches set predictions_enabled=false where id=m;
 update public.matches set scheduled_start=clock_timestamp()+interval '0.1 second',predictions_enabled=true where id=m;
 perform pg_sleep(0.2);
 perform set_config('role','authenticated',true);perform set_config('request.jwt.claim.sub',u::text,true);
 begin perform public.submit_match_prediction(m,6,2);raise exception 'FAIL late prediction';exception when others then if sqlerrm not like '%deadline%' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',a::text,true);
 begin perform public.edit_knockout(tid,'result',m,'{"home_score":5,"away_score":3}');raise exception 'FAIL invalid score';exception when others then if sqlerrm like 'FAIL%' then raise;end if;end;
 perform public.edit_knockout(tid,'result',m,'{"home_score":6,"away_score":3}');
 r:=public.get_knockout_schema(tid);
 if not exists(select 1 from jsonb_array_elements(r->'matches')x where x->>'id'=final::text and x->>'home'='QA A' and x->>'away'='QA B' and (x->>'enabled')::boolean) then raise exception 'FAIL advancement and opening';end if;
 perform set_config('request.jwt.claim.sub',u::text,true);perform public.submit_match_prediction(final,3,1);
 perform set_config('request.jwt.claim.sub',a::text,true);
 begin perform public.edit_knockout(tid,'result',m,'{"home_score":3,"away_score":6,"reason":"QA winner correction"}');raise exception 'FAIL downstream predictions overwritten';exception when others then if sqlerrm like 'FAIL%' then raise;end if;end;
 perform public.edit_knockout(tid,'result',m,'{"home_score":6,"away_score":2,"reason":"QA score correction"}');
 perform public.edit_knockout(tid,'postpone',final,'{"reason":"QA uitstel"}');
 perform public.edit_knockout(tid,'schedule',final,jsonb_build_object('start',now()+interval '3 days','unit','sets','first_to',3,'reason','QA nieuwe tijd'));
 perform set_config('role','postgres',true);
 if (select predictions_enabled from public.matches where id=final) then raise exception 'FAIL implicit reopen';end if;
 perform set_config('role','authenticated',true);
 perform public.edit_knockout(tid,'open',final,'{"reason":"QA bewuste heropening"}');
 -- Football knockout: tied score does not turn penalty kicks into prediction goals.
 ft:=public.create_knockout_tournament('QA teams',football,'teams',array['QA Team A','QA Team B'],now()+interval '1 day','[{"unit":"goals","winner_points":1,"exact_points":3}]');
 r:=public.get_knockout_schema(ft);fmatch:=(r->'matches'->0->>'id')::uuid;
 perform public.edit_knockout(ft,'start',fmatch,'{"reason":"QA vroeg gestart"}');
 begin perform public.edit_knockout(ft,'result',fmatch,'{"home_score":1,"away_score":1}');raise exception 'FAIL tied knockout without winner';exception when others then if sqlerrm like 'FAIL%' then raise;end if;end;
 perform public.edit_knockout(ft,'result',fmatch,'{"home_score":1,"away_score":1,"winner_slot":1}');
 perform public.edit_knockout(ft,'result',fmatch,'{"home_score":1,"away_score":1,"winner_slot":2,"reason":"QA tie winner correction"}');
 r:=public.get_knockout_schema(ft);if r->'matches'->0->>'winner_slot'<>'2' then raise exception 'FAIL tied winner correction';end if;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('role','anon',true);
 begin perform public.get_knockout_schema(tid);raise exception 'FAIL anon schema';exception when insufficient_privilege then null;end;
 perform set_config('role','postgres',true);
end $$;
select 'PASS: knockout, byes, roles, schema visibility, deadlines, propagation, correction protection, explicit reopening and football tie winner' as result;
rollback;
